"""Small durable content/event store. SQLite transactions define exactly-once effects."""

from __future__ import annotations

import hashlib
import json
import os
import sqlite3
import tempfile
from collections.abc import Callable
from contextlib import contextmanager
from datetime import UTC, datetime
from pathlib import Path

from .contracts import ConflictError, ContractError, canonical, digest
from .private_paths import validate_private_path


def now() -> str:
    return datetime.now(UTC).isoformat()


class Store:
    def __init__(self, path: Path | str):
        self.path = Path(path).expanduser().resolve()
        validate_private_path(self.path, error_type=ContractError)
        self.path.mkdir(parents=True, exist_ok=True, mode=0o700)
        self.blobs = self.path / "blobs"
        self.blobs.mkdir(exist_ok=True, mode=0o700)
        self.db = sqlite3.connect(self.path / "campaign.sqlite3", isolation_level=None, timeout=30)
        self.db.row_factory = sqlite3.Row
        self.db.execute("PRAGMA journal_mode=WAL")
        self.db.execute("PRAGMA synchronous=FULL")
        self.db.execute("PRAGMA foreign_keys=ON")
        self.db.executescript("""
            CREATE TABLE IF NOT EXISTS objects(
                kind TEXT NOT NULL, id TEXT NOT NULL, digest TEXT NOT NULL,
                data TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(kind,id));
            CREATE TABLE IF NOT EXISTS meta(key TEXT PRIMARY KEY, data TEXT NOT NULL);
            CREATE TABLE IF NOT EXISTS calls(
                id TEXT PRIMARY KEY, digest TEXT NOT NULL, result TEXT NOT NULL);
            CREATE TABLE IF NOT EXISTS events(
                sequence INTEGER PRIMARY KEY AUTOINCREMENT, kind TEXT NOT NULL,
                data TEXT NOT NULL, created_at TEXT NOT NULL);
        """)
        version = self.meta("schema_version")
        if version not in (None, 1):
            raise ContractError("unsupported store schema version")
        with self.transaction():
            self.set_meta("schema_version", 1)

    def close(self):
        self.db.close()

    @contextmanager
    def transaction(self):
        self.db.execute("BEGIN IMMEDIATE")
        try:
            yield
        except BaseException:
            self.db.execute("ROLLBACK")
            raise
        else:
            self.db.execute("COMMIT")

    def action(self, call_id: str, payload: dict, effect: Callable[[], dict]) -> dict:
        """Commit mutation, audit and call receipt together; conflicts fail closed."""
        signature = digest(payload)
        with self.transaction():
            previous = self.db.execute("SELECT * FROM calls WHERE id=?", (call_id,)).fetchone()
            if previous:
                if previous["digest"] != signature:
                    raise ConflictError(f"call ID {call_id!r} has different content")
                return json.loads(previous["result"])
            result = effect()
            encoded = canonical(result)
            self.db.execute("INSERT INTO calls VALUES(?,?,?)", (call_id, signature, encoded))
            self.event(payload["operation"], {"call_id": call_id, "result": result})
            return json.loads(encoded)

    def put(self, kind: str, identifier: str, data: dict) -> bool:
        signature = digest(data)
        previous = self.db.execute(
            "SELECT digest FROM objects WHERE kind=? AND id=?", (kind, identifier)
        ).fetchone()
        if previous:
            if previous["digest"] != signature:
                raise ConflictError(f"immutable {kind} {identifier!r} already exists")
            return False
        self.db.execute(
            "INSERT INTO objects VALUES(?,?,?,?,?)",
            (kind, identifier, signature, canonical(data), now()),
        )
        return True

    def get(self, kind: str, identifier: str) -> dict:
        row = self.db.execute(
            "SELECT data,digest FROM objects WHERE kind=? AND id=?", (kind, identifier)
        ).fetchone()
        if row is None:
            raise ContractError(f"unknown {kind}: {identifier}")
        data = json.loads(row["data"])
        if digest(data) != row["digest"]:
            raise ContractError(f"stored {kind} integrity check failed")
        return data

    def all(self, kind: str) -> list[dict]:
        rows = self.db.execute(
            "SELECT id FROM objects WHERE kind=? ORDER BY rowid", (kind,)
        ).fetchall()
        return [self.get(kind, row["id"]) for row in rows]

    def has(self, kind: str, identifier: str) -> bool:
        return (
            self.db.execute(
                "SELECT 1 FROM objects WHERE kind=? AND id=?", (kind, identifier)
            ).fetchone()
            is not None
        )

    def meta(self, key: str):
        row = self.db.execute("SELECT data FROM meta WHERE key=?", (key,)).fetchone()
        return json.loads(row[0]) if row else None

    def set_meta(self, key: str, value):
        self.db.execute(
            "INSERT INTO meta VALUES(?,?) ON CONFLICT(key) DO UPDATE SET data=excluded.data",
            (key, canonical(value)),
        )

    def event(self, kind: str, data: dict):
        self.db.execute(
            "INSERT INTO events(kind,data,created_at) VALUES(?,?,?)", (kind, canonical(data), now())
        )

    def history(self) -> list[dict]:
        return [
            {
                "sequence": r["sequence"],
                "kind": r["kind"],
                "data": json.loads(r["data"]),
                "created_at": r["created_at"],
            }
            for r in self.db.execute("SELECT * FROM events ORDER BY sequence")
        ]

    def blob(self, source: Path, max_bytes: int) -> dict:
        """Stream large originals into immutable content storage, never a personal path."""
        source = Path(source)
        if not source.is_file():
            raise ContractError(f"raw source is not a regular file: {source.name}")
        hasher = hashlib.sha256()
        length = 0
        fd, temporary = tempfile.mkstemp(prefix="incoming-", dir=self.blobs)
        try:
            with source.open("rb") as incoming, os.fdopen(fd, "wb") as outgoing:
                while chunk := incoming.read(1024 * 1024):
                    length += len(chunk)
                    if length > max_bytes:
                        raise ContractError("raw artifact exceeds configured max_file_bytes")
                    hasher.update(chunk)
                    outgoing.write(chunk)
                outgoing.flush()
                os.fsync(outgoing.fileno())
            sha256 = hasher.hexdigest()
            destination = self.blobs / sha256
            if destination.exists():
                if self.file_digest(destination) != sha256:
                    raise ContractError("stored raw artifact failed integrity check")
                Path(temporary).unlink()
            else:
                os.replace(temporary, destination)
                directory_fd = os.open(self.blobs, os.O_RDONLY)
                try:
                    os.fsync(directory_fd)
                finally:
                    os.close(directory_fd)
            return {"sha256": sha256, "size_bytes": length}
        finally:
            if Path(temporary).exists():
                Path(temporary).unlink()

    @staticmethod
    def file_digest(path: Path) -> str:
        hasher = hashlib.sha256()
        with path.open("rb") as stream:
            while chunk := stream.read(1024 * 1024):
                hasher.update(chunk)
        return hasher.hexdigest()

    def verify_blob(self, sha256: str):
        path = self.blobs / sha256
        if not path.is_file() or self.file_digest(path) != sha256:
            raise ContractError("missing or modified raw artifact")
